pub(super) fn widget_host(w: &mut String, ctx: &mut RenderCtx<'_>, package: u32, index: usize) {
    dw!(
        w,
        "// Generated by corpus-gen. Deterministic corpus; do not edit.\n\n"
    );
    dw!(w, "/// Widget host file paired with a `part` file.\n\n");
    dw!(w, "part 'widget_{index:05}_part.dart';\n\n");
    dw!(
        w,
        "class HostWidget{package}_{index} {{\n  final List<Piece{package}_{index}> pieces = <Piece{package}_{index}>[];\n\n  String render() => pieces.map((piece) => piece.tile()).join('|');\n}}\n"
    );
    ctx.coverage.hit(Cell::PartOfPair);
}

pub(super) fn widget_part(w: &mut String, ctx: &mut RenderCtx<'_>, package: u32, index: usize) {
    let piece = format!("Piece{package}_{index}");
    dw!(
        w,
        "// Generated by corpus-gen. Deterministic corpus; do not edit.\n\n"
    );
    dw!(w, "part of 'widget_{index:05}.dart';\n\n");
    dw!(w, "/// Private piece contributed by the part file.\n");
    dw!(
        w,
        "class {piece} {{\n  const {piece}();\n\n  String tile() => 'piece-{package:04}-{index:05}';\n}}\n"
    );
    ctx.coverage.hit(Cell::PartOfPair);
}

