const TEST_BLOCKS: [&str; 10] = [
    "  test('named record pattern', () {\n    final (:width, :height) = (width: 3, height: 4);\n    expect(width * height, 12);\n  });\n",
    "  test('positional record pattern', () {\n    final (a, b) = (7, 8);\n    expect(a + b, 15);\n  });\n",
    "  test('list pattern in if-case', () {\n    final values = <int>[1, 2, 3, 4];\n    if (values case [var first, var second, ...var rest]) {\n      expect(first + second, 3);\n      expect(rest.length, 2);\n    } else {\n      fail('pattern should match');\n    }\n  });\n",
    "  test('map pattern in switch', () {\n    const value = <String, int>{'b': 2};\n    final label = switch (value) {\n      {'a': int a} => 'a:$a',\n      {'b': int b} => 'b:$b',\n      _ => 'other',\n    };\n    expect(label, 'b:2');\n  });\n",
    "  test('collection control flow', () {\n    final values = <int>[\n      for (var i = 0; i < 5; i++)\n        if (i.isEven) i,\n      ...[7, 8],\n    ];\n    expect(values.length, 5);\n  });\n",
    "  test('relational switch expression', () {\n    expect(switch (9) {\n      > 8 => 'high',\n      _ => 'low',\n    }, 'high');\n  });\n",
    "  test('null safety fallback', () {\n    String? maybe;\n    expect(maybe ?? 'fallback', 'fallback');\n  });\n",
    "  test('cascade', () {\n    final buffer = StringBuffer()\n      ..write('a')\n      ..write('b');\n    expect(buffer.toString(), 'ab');\n  });\n",
    "  test('numeric literals', () {\n    expect(0xFF, 255);\n    final scaled = 1.5e2 + 0x10;\n    expect(scaled, 166);\n  });\n",
    "  test('string interpolation', () {\n    final tag = 'v${1 + 1}';\n    final label = 'value-$tag end';\n    expect(label, 'value-v2 end');\n  });\n",
];

pub(super) fn test_file(w: &mut String, ctx: &mut RenderCtx<'_>, ordinal: usize) {
    let feature = ordinal % ctx.plan.packages as usize;
    dw!(
        w,
        "// Generated by corpus-gen. Deterministic corpus; do not edit.\n"
    );
    dw!(w, "import 'package:test/test.dart';\n");
    dw!(w, "import 'package:core/core.dart';\n");
    dw!(
        w,
        "import 'package:feature_{feature:04}/feature_{feature:04}.dart';\n\n"
    );
    dw!(w, "void main() {{\n");
    for j in 0..4 {
        let pick = (ordinal * 3 + j * 7) % TEST_BLOCKS.len();
        w.push_str(TEST_BLOCKS[pick]);
    }
    dw!(w, "}}\n");
    ctx.coverage.hit(Cell::PackageUriImport);
}
